								if (bodyForm instanceof Crystal){
									((Crystal) bodyForm).setDurability(BodyForm.duration()*1.5f);
								}

								Sample.INSTANCE.play(Assets.Sounds.TELEPORT);
								Weapon w = new WornShortsword();
