			int initialOfsCell = start + xOfs + yOfs;
			HashSet<Integer> cells = new HashSet<>();
			int cell = initialOfsCell;
			do {
				cells.add(cell);
				cell += -dirX + dirY*Dungeon.level.width();
			} while (Dungeon.level.insideMap(cell) && !Dungeon.level.solid[cell]);
			cell = initialOfsCell;
