							if ((bouncepos == -1 || Dungeon.level.trueDistance(pos, leapPos+i) < Dungeon.level.trueDistance(pos, bouncepos))
									&& Actor.findChar(leapPos+i) == null && !Dungeon.level.solid[leapPos+i]){
								bouncepos = leapPos+i;
							}
						}
					}

					if (bouncepos == -1) {
						leapPos = -1;
						return true;
					} else {
