			enemy = null;
			enemy = chooseEnemy();
			if (enemy != null && enemy != oldEnemy) {
				recursing = true;
				boolean result = act(enemyInFOV, justAlerted);
				recursing = false;
				return result;
			}

			//attempt to use an ability, even if enemy can't be decided
			//Tengu is always hunting, so we don't lose enemy in this case
			if (canUseAbility()){
				return useAbility();
			}

			spend( TICK );
			return true;

		}

