			if (curColor == bgColor) {
				y++;
				for (x = 3; x <= 12; x++) {
					curColor = tx.getPixel(col * size + x, row * size + y);
					if (curColor != bgColor) break;
				}
			}

			p.x = x * image.scale.x;
			p.y = y * image.scale.y;

			highlightPositions.put(index, new Point(x, y));
