					GLog.w( Messages.get(this,            ) );
					return;
				}
			}
		}

		if (action == AC_ZAP ){

			curUser = hero;
			int chargesToUse = Dungeon.depth > 20 ? 2 : 1;

			if (!isEquipped( hero )) {
				GLog.i( Messages.get(Artifact.class,                ) );
				QuickSlotButton.cancel();

			} else if (charge < chargesToUse) {
				GLog.i( Messages.get(this,            ) );
				QuickSlotButton.cancel();

			} else {
				GameScene.selectCell(zapper);
			}

		} else if (action == AC_SET) {

			returnDepth = Dungeon.depth;
			returnPos = hero.pos;

			hero.spend( LloydsBeacon.TIME_TO_USE );
			hero.busy();

			hero.sprite.operate( hero.pos );
			Sample.INSTANCE.play( Assets.Sounds.BEACON );

			GLog.i( Messages.get(this,         ) );

		} else if (action == AC_RETURN) {

			if (returnDepth == Dungeon.depth) {
				ScrollOfTeleportation.appear( hero, returnPos );
				for(Mob m : Dungeon.level.mobs){
					if (m.pos == hero.pos){

						for(int i : PathFinder.NEIGHBOURS8){
							if (Actor.findChar(m.pos+i) == null && Dungeon.level.passable[m.pos + i]){
