public Point pointInside(Point from, int n){
		Point step = new Point(from);
		if (from.x == left) {
			step.offset( +n, 0 );
		} else if (from.x == right) {
			step.offset( -n, 0 );
		} else if (from.y == top) {
			step.offset( 0, +n );
		} else if (from.y == bottom) {
			step.offset( 0, -n );
		}
		return step;
	}

