@Override
		public Tilemap create() {
			Tilemap v = super.create();
			int[] data = new int[tileW*tileH];
			for (int x = 0; x < tileW; x++){
				for (int y = 0; y < tileH; y++){

					//corners
					if ((x == 0 || x == tileW-1) && (y == 0 || y == tileH-1)){
						data[x + tileW*y] = -1;

					//adjacent to corners
					} else if ((x == 1 && y == 0) || (x == 0 && y == 1)){
						data[x + tileW*y] = 0;

					} else if ((x == tileW-2 && y == 0) || (x == tileW-1 && y == 1)){
						data[x + tileW*y] = 1;

					} else if ((x == 1 && y == tileH-1) || (x == 0 && y == tileH-2)){
						data[x + tileW*y] = 2;

					} else if ((x == tileW-2 && y == tileH-1) || (x == tileW-1 && y == tileH-2)) {
						data[x + tileW*y] = 3;

					//sides
					} else if (x == 0){
						data[x + tileW*y] = 4;

					} else if (y == 0){
						data[x + tileW*y] = 5;

					} else if (x == tileW-1){
						data[x + tileW*y] = 6;

					} else if (y == tileH-1){
						data[x + tileW*y] = 7;

					//inside
					} else {
						data[x + tileW*y] = 8;
					}

				}
			}
			v.map( data, tileW );
			return v;
		}

