					if (y == 0){
						Painter.set(level, left + w/2, top-1, Terrain.DOOR);
					} else if (y == cols-1){
						Painter.set(level, left + w/2-1, top+h, Terrain.DOOR);
					} else if (x == 0) {
						Painter.set(level, left-1, top+h/2-1, Terrain.DOOR);
					} else if (x == rows-1){
