@Override
	public float levelExplorePercent(int depth) {
		// Each 1% of tiles seen = 1.25% explored. 80% seen = 100% explored
		int seen = 0, total = 0;
		for (int i = 0; i < length; i++){
			if (discoverable[i]) total++;
			if (visited[i]) seen++;
		}
		return Math.min(1, (seen*1.25f)/total);
	}

