		clearItem(item); //we don't want to allow the same item in multiple slots.
		slots[slot] = item;
	}

public void clearSlot(int slot){
		slots[slot] = null;
	}

public void reset(){
		slots = new Item[SIZE];
	}

public Item getItem(int slot){
		return slots[slot];
	}

