			}

		} else if (!DungeonTileSheet.wallStitcheable(tile) && !Dungeon.level.pit[pos]) {



			if (wall(pos-mapWidth) && map[pos] != Terrain.ALCHEMY) {
				curr += WALL_ABOVE;


