			} else {


				if (wall(pos - 1)) {
					curr += WALL_LEFT;
				} else if (wall(pos + mapWidth - 1)) {
					if (wall(pos - mapWidth - 1)) {
						curr += WALL_LEFT_BOTH;
					} else {
						curr += WALL_LEFT_BELOW;
					}
				} else if (wall(pos - mapWidth - 1)) {
					curr += WALL_LEFT_ABOVE;
				}


				if (wall(pos + 1)) {
					curr += WALL_RIGHT;
				} else if (wall(pos + mapWidth + 1)) {
					if (wall(pos - mapWidth + 1)) {
						curr += WALL_RIGHT_BOTH;
					} else {
						curr += WALL_RIGHT_BELOW;
					}
				} else if (wall(pos - mapWidth + 1)) {
