			if (i1 instanceof Scroll)   i1Idx += 1000;
			if (i1 instanceof Ring)     i1Idx += 2000;

			if (i2 instanceof Scroll)   i2Idx += 1000;
			if (i2 instanceof Ring)     i2Idx += 2000;

			return i1Idx - i2Idx;
		}
	};

