					if (text.startsWith( GLog.HIGHLIGHT )) {
						text = text.substring( GLog.HIGHLIGHT.length() );
						color = CharSprite.NEUTRAL;
					}

					if (lastEntry != null && color == lastColor && lastEntry.nLines < maxLines) {

						String lastMessage = lastEntry.text();
