			score.setPos(WIDTH - score.width(), top);
			content.add(score);

			top = (int) day.bottom() + 6;
			if (first){
				top += 2;
				first = false;
			}
		}

		content.setRect(0, 0, WIDTH, top);
		pane.setRect(0, 0, WIDTH, HEIGHT);

	}

