			final Languages currLang = Messages.lang();

			txtLangInfo = PixelScene.renderTextBlock(6);
			String info =     + Messages.titleCase(currLang.nativeName()) +       ;
			if (currLang == Languages.ENGLISH) info +=                                                         ;
