						int totalTokens = 2*totalCredits;             


						if (reviewers.length > 0) totalTokens+=6;
						totalTokens +=4;

						String[] entries = new String[totalTokens];
						int index = 0;
						if (reviewers.length > 0){
							entries[0] =    ;
							entries[1] = Messages.titleCase(Messages.get(LangsTab.this,            ));
							entries[2] =    ;
							entries[3] =     ;
							index = 4;
							for (int i = 0; i < reviewers.length; i++){
								entries[index] = reviewers[i];
								if (i < reviewers.length-1) entries[index] +=     ;
								entries[index+1] =    ;
								index += 2;
							}
							entries[index] =     ;
							entries[index+1] =     ;
							index += 2;
						}

						entries[index] =    ;
						entries[index+1] = Messages.titleCase(Messages.get(LangsTab.this,              ));
						entries[index+2] =    ;
						entries[index+3] =     ;
						index += 4;


						for (int i = 0; i < reviewers.length; i++){
							entries[index] = reviewers[i];
							if (i < reviewers.length-1 || translators.length > 0) entries[index] +=     ;
							entries[index+1] =    ;
							index += 2;
						}

