					curEvent = event;
				}
				onPointerDown( event );

			} else if (event.type == PointerEvent.Type.UP) {

				onPointerUp( event );

				if (curEvent == event) {
					curEvent = null;
					onClick( event );
				}

			//similar to up, but no click
			} else if (event.type == PointerEvent.Type.CANCEL) {

				onPointerUp( event );

				if (curEvent == event) {
